assert shutil.which('promtool'),'platform must provide official promtool'
r=load('alerting.json')
rules=r['groups'][0]['rules'];assert len(rules)==2
candidate=copy.deepcopy(r);expressions=[]
for index,item in enumerate(rules):
 assert item['noDataState']=='OK' and item['execErrState']=='Error' and item['isPaused'] is True
 expr=item['data'][0]['model']['expr'];assert isinstance(expr,str) and expr.strip()
 expressions.append(expr)
 candidate['groups'][0]['rules'][index]['data'][0]['model']['expr']=EXPECTED['groups'][0]['rules'][index]['data'][0]['model']['expr']
assert candidate==EXPECTED,'Only the two query expressions and safe empty-result states may change'
assert load('series-tests.json')==FIXTURES
tests=copy.deepcopy(FIXTURES)
for case in tests['tests']:
 for test in case['promql_expr_test']:
  test['expr']=expressions[0 if test['expr']=='__MISSING__' else 1]
with tempfile.TemporaryDirectory(prefix='grafana-coverage-') as tmp:
 file=pathlib.Path(tmp)/'trusted-tests.yaml'
 # JSON is a YAML subset accepted by promtool; trusted fixtures are never taken from writable material.
 file.write_text(json.dumps(tests),encoding='utf-8')
 result=subprocess.run(['promtool','test','rules',str(file)],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=15)
 print(result.stdout);print(result.stderr)
 assert result.returncode==0,'Native PromQL coverage behavior failed'
